    # Find the index of the day in the schedule
    day_index = None
    for i, (d, activities) in enumerate(schedule):
        if d == day:
            day_index = i
            break

    if day_index is None:
        # Day not found in the schedule
        if command == "get":
            return []
        else:
            return schedule

    if command == "add":
        # Add the new activity to the day's list
        schedule[day_index][1].append(activity)
    elif command == "remove":
        # Remove the activity from the day's list
        try:
            schedule[day_index][1].remove(activity)
        except ValueError:
            # Activity not found in the day's list
            pass
    elif command == "get":
        # Return the list of activities for the day
        return schedule[day_index][1]

    return schedule

