    total_time = 0
    time_regex = r'(\d+)\s*(hours?|hrs?|minutes?|mins?)'

    for instruction in instructions:
        matches = re.findall(time_regex, instruction, re.IGNORECASE)
        for match in matches:
            time, unit = match
            time = int(time)
            if unit.startswith('h'):
                total_time += time * 60
            else:
                total_time += time

    return total_time

