    import re
    from collections import Counter

    # Define a set of common stopwords
    stopwords = set(['a', 'an', 'and', 'are', 'as', 'at', 'be', 'but', 'by', 'for', 'if', 'in', 'into', 'is', 'it', 'no', 'not', 'of', 'on', 'or', 'such', 'that', 'the', 'their', 'then', 'there', 'these', 'they', 'this', 'to', 'was', 'will', 'with'])

    # Initialize a Counter to store word/phrase counts
    word_counts = Counter()

    # Iterate through each piece of feedback
    for feedback in feedback_list:
        # Remove punctuation and convert to lowercase
        feedback = re.sub(r'[^\w\s]', '', feedback.lower())

        # Split feedback into words/phrases
        words = feedback.split()

        # Iterate through words/phrases up to the specified length
        for i in range(len(words)):
            for j in range(1, max_phrase_length + 1):
                phrase = ' '.join(words[i:i+j])
                if phrase not in stopwords:
