    def backtrack(start, combination):
        result.append(''.join(combination))

        for i in range(start, len(s)):
            if s[i] not in combination:
                combination.append(s[i])
                backtrack(i + 1, combination)
                combination.pop()

    backtrack(0, [])
    return sorted(set(result))

