def calculate_molar_mass(formula):
    atomic_masses = {'H': 1.01, 'C': 12.01, 'O': 16.00}
    total_mass = 0

    i = 0
    while i < len(formula):
        element = formula[i]
        if element.isalpha():
            if i + 1 < len(formula) and formula[i + 1].isdigit():
                count = int(formula[i + 1])
                i += 2
            else:
                count = 1
                i += 1

