def evaluate_expression(expression):
    result = 0
    sign = '+'
    current_num = 0
    for char in expression:
        if char.isdigit():
            current_num = current_num * 10 + int(char)
        else:
            if sign == '+':
                result += current_num
            else:
                result -= current_num
            sign = char
            current_num = 0
