def can_partition(nums):
    total_sum = sum(nums)
    if total_sum % 2 != 0:
        return False

    target_sum = total_sum // 2
    dp = set()
    dp.add(0)

    for num in nums:
        next_dp = dp.copy()
        for t in dp:
            next_dp.add(t + num)
        dp = next_dp

    return target_sum in dp

